    if (id.indexOf("wa.gw.msging.net") !== -1 || id.indexOf("tunnel.msging.net") !== -1 || id.indexOf("@wa") !== -1) {
        return "WhatsApp";
    }
    return "WhatsApp"; // Default WhatsApp para garantir renderização interativa
}

