function run(nlpStatus, nlpResponse) {
    var result = {
        acaoSeguinte: "PEDIR_CPF",
        listaMedicosJson: "[]",
        externalLink: "",
        externalPhone: "",
        isInternal: "false",
        queueName: "Recepção Central / Suporte"
    };
    try {
        if (parseInt(nlpStatus, 10) !== 200 || !nlpResponse) {
            return JSON.stringify(result);
        }
        var response = JSON.parse(nlpResponse);

        // Identifica lista de médicos (matches ou doctors)
        var doctorsList = response.matches || response.doctors || [];
        var isAmbiguous = (response.hasAmbiguity === true) || 
                          (response.intent === "DESAMBIGUACAO") || 
                          (response.routeType === "DESAMBIGUACAO") || 
                          (response.acaoSeguinte === "EXIBIR_LISTA_DESAMBIGUACAO") ||
                          (Array.isArray(doctorsList) && doctorsList.length > 1);

        if (isAmbiguous && doctorsList.length > 0) {
            result.acaoSeguinte = "MENU_DESAMBIGUACAO";
            result.listaMedicosJson = JSON.stringify(doctorsList);
        } else {
            result.acaoSeguinte = "PEDIR_CPF";

            if (doctorsList.length === 1) {
                var match = doctorsList[0];
                if (match.externalLink) result.externalLink = match.externalLink;
                if (match.externalPhone) result.externalPhone = match.externalPhone;
                if (match.isInternal !== undefined) {
                    result.isInternal = (match.isInternal === true || match.isInternal === "true" || match.isInternal === "TRUE") ? "true" : "false";
                }
                if (match.queue || match.queueName) {
                    result.queueName = match.queue || match.queueName;
                }
            } else {
                if (response.externalLink) result.externalLink = response.externalLink;
                if (response.externalPhone) result.externalPhone = response.externalPhone;
                if (response.isInternal !== undefined) {
                    result.isInternal = (response.isInternal === true || response.isInternal === "true" || response.isInternal === "TRUE") ? "true" : "false";
                }
                if (response.queue || response.queueName) {
                    result.queueName = response.queue || response.queueName;
                }
            }
        }
    } catch (e) {
        result.acaoSeguinte = "PEDIR_CPF";
    }
    return JSON.stringify(result);
}

