function run(cadastroNomeRaw) {
    try {
        if (!cadastroNomeRaw) return JSON.stringify({ nomeValido: "INVALID", cleanNome: "" });
        var cleanNome = cadastroNomeRaw.trim().replace(/\s+/g, " ");
        var parts = cleanNome.split(" ");
        if (parts.length < 2 || cleanNome.length < 5) {
            return JSON.stringify({ nomeValido: "INVALID", cleanNome: "" });
        }
        return JSON.stringify({ nomeValido: "VALID", cleanNome: cleanNome });
    } catch (e) {
        return JSON.stringify({ nomeValido: "INVALID", cleanNome: "" });
    }
}

