function run(cadastroNascimentoRaw) {
    try {
        if (!cadastroNascimentoRaw) return JSON.stringify({ dataValida: "INVALID", cleanDate: "" });
        var digits = cadastroNascimentoRaw.toString().replace(/\D/g, "");
        if (digits.length !== 8) return JSON.stringify({ dataValida: "INVALID", cleanDate: "" });
        var day = parseInt(digits.substring(0, 2), 10);
        var month = parseInt(digits.substring(2, 4), 10);
        var year = parseInt(digits.substring(4, 8), 10);
        if (month < 1 || month > 12 || day < 1 || day > 31 || year < 1910 || year > 2026) {
            return JSON.stringify({ dataValida: "INVALID", cleanDate: "" });
        }
        var formattedMonth = month < 10 ? "0" + month : "" + month;
        var formattedDay = day < 10 ? "0" + day : "" + day;
        return JSON.stringify({ dataValida: "VALID", cleanDate: year + "-" + formattedMonth + "-" + formattedDay });
    } catch (e) {
        return JSON.stringify({ dataValida: "INVALID", cleanDate: "" });
    }
}

