function run(isInternal, externalLink, queueName) {
    try {
        var link = (externalLink || "").toString().trim();
        var internal = (isInternal === true || isInternal === "true" || isInternal === "TRUE");
        var defaultQueue = "Recepção Central / Suporte";
        var queue = (queueName && queueName.toString().trim().length > 0) ? queueName.toString().trim() : defaultQueue;

        if (!internal && link.length > 5) {
            return JSON.stringify({ routeType: "EXTERNAL", selectedQueue: queue });
        } else if (internal) {
            return JSON.stringify({ routeType: "INTERNAL", selectedQueue: queue });
        } else {
            return JSON.stringify({ routeType: "MENU_POS_CPF", selectedQueue: queue });
        }
    } catch (e) {
        return JSON.stringify({ routeType: "MENU_POS_CPF", selectedQueue: "Recepção Central / Suporte" });
    }
}

