function run(appointmentsStatus, appointmentsResponse) {
    try {
        var status = parseInt(appointmentsStatus, 10);
        if (status !== 200 || !appointmentsResponse) {
            return "Não encontramos agendamentos futuros para o seu cadastro.";
        }
        var data = JSON.parse(appointmentsResponse);
        if (!data.items || data.items.length === 0) {
            return "Você não possui agendamentos futuros marcados.";
        }
        var message = "📅 *Seus Próximos Agendamentos:*\n\n";
        for (var i = 0; i < data.items.length; i++) {
            var item = data.items[i];
            message += "• *Data:* " + item.date + " às " + item.time + "\n";
            message += "  *Médico:* " + item.doctorName + "\n";
            message += "  *Especialidade:* " + item.specialty + "\n\n";
        }
        return message;
    } catch (e) {
        return "Desculpe, ocorreu uma falha ao consultar seus agendamentos.";
    }
}

